CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leases (key TEXT PRIMARY KEY, owner TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots (t INTEGER PRIMARY KEY, model TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mappings (id TEXT PRIMARY KEY, created INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account_items (owner TEXT NOT NULL, kind TEXT NOT NULL, id TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(owner,kind,id));
CREATE TABLE IF NOT EXISTS alert_state (owner TEXT NOT NULL, id TEXT NOT NULL, matched INTEGER NOT NULL DEFAULT 0, last_fired INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(owner,id));
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, owner TEXT NOT NULL, rule_id TEXT NOT NULL, created INTEGER NOT NULL, is_read INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS notifications_owner_created ON notifications(owner,created DESC);
CREATE INDEX IF NOT EXISTS notifications_created ON notifications(created);
CREATE TABLE IF NOT EXISTS telemetry (day TEXT NOT NULL, event TEXT NOT NULL, placement TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(day,event,placement));
